def format_report(rows, footer):
    lines = []
    for name, score in rows:
        lines.append(f'{name}={score}')
    lines.append(str(footer))
    if len(rows) > 1:
        total = 0
        best = rows[0][1]
        for name, score in rows:
            total += score
            if score > best:
                best = score
        lines.append(f'{len(rows)} rows, sum {total}, best {best}')
    return '\n'.join(lines)

