def average(numbers):
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)

def last_pair(values):
    if len(values) < 2:
        return (None, None)
    return (values[-2], values[-1])

def bucket(value, limits):
    count = 0
    far = 0
    for lim in limits:
        if value > lim:
            count += 1
            far = value - lim
    return count, far

